-- CloudDesk synthetic demo seed: 20 employees, 5 technicians, 100 tickets
-- Existing records are preserved. Safe to run again: deterministic emails and titles.
BEGIN;
CREATE TEMP TABLE seed_users (name text, email text, role text) ON COMMIT DROP;
CREATE TEMP TABLE seed_tickets (title text, description text, status text, priority text, creator_email text, assignee_email text) ON COMMIT DROP;
SELECT s.title, s.description, s.status, s.priority, creator.id, assignee.id, assignee.name
FROM seed_tickets s
JOIN users creator ON creator.email=s.creator_email
LEFT JOIN users assignee ON assignee.email=s.assignee_email
WHERE NOT EXISTS (SELECT 1 FROM tickets t WHERE t.title=s.title);
SELECT (SELECT count(*) FROM users WHERE email LIKE 'demo.%@example.com') AS demo_users, (SELECT count(*) FROM tickets WHERE title LIKE '[DEMO-%') AS demo_tickets;
COMMIT;
